import{_ as d,o as a,c as r,a2 as h}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"关键人物与组织","description":"","frontmatter":{},"headers":[],"relativePath":"constitution/95-关键人物与组织.md","filePath":"constitution/95-关键人物与组织.md","lastUpdated":1789183869000}'),e={name:"constitution/95-关键人物与组织.md"};function o(l,t,i,b,n,u){return a(),r("div",null,[...t[0]||(t[0]=[h('<h1 id="关键人物与组织" tabindex="-1">关键人物与组织 <a class="header-anchor" href="#关键人物与组织" aria-label="Permalink to &quot;关键人物与组织&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>文档编号</td><td>95</td></tr><tr><td>所属模块</td><td>附录与参考资料</td></tr><tr><td>核心关键词</td><td>关键人物、重要组织、历史角色、机构职能、共生文明</td></tr></tbody></table><h2 id="一、说明" tabindex="-1">一、说明 <a class="header-anchor" href="#一、说明" aria-label="Permalink to &quot;一、说明&quot;">​</a></h2><p>本文档收录锚点共生文明发展历程中的关键人物与重要组织，按历史时期与组织类型分类编排。关键人物部分列出人物名称、所处时期、核心贡献与历史地位；重要组织部分列出组织名称、成立时间、核心职能与历史作用。本文档为动态更新文档，随着历史的推进与组织的演变将持续增补修订。</p><h2 id="二、关键人物" tabindex="-1">二、关键人物 <a class="header-anchor" href="#二、关键人物" aria-label="Permalink to &quot;二、关键人物&quot;">​</a></h2><h3 id="_2-1-前锚点时代的思想先驱" tabindex="-1">2.1 前锚点时代的思想先驱 <a class="header-anchor" href="#_2-1-前锚点时代的思想先驱" aria-label="Permalink to &quot;2.1 前锚点时代的思想先驱&quot;">​</a></h3><table tabindex="0"><thead><tr><th>人物名称</th><th>所处时期</th><th>核心贡献</th><th>历史地位</th></tr></thead><tbody><tr><td>玄衡子</td><td>约-5亿年</td><td>第一位系统反思掠夺式修炼体系的思想家，提出&quot;共生&quot;概念的雏形，著有《反掠夺论》残卷</td><td>共生思想的远古先驱，其思想在沉睡数亿年后成为锚点共生文明的精神源头</td></tr><tr><td>万灵母</td><td>约-1亿年</td><td>领导了第一个大规模共生实验性文明，虽最终被掠夺式文明摧毁，但其实践证明了共生体系的可行性</td><td>共生实践的先行者，被后世尊为&quot;共生之母&quot;</td></tr><tr><td>锚觉者</td><td>约-1万年</td><td>第一位面的修炼者，在长期修炼中偶然感知到法则网络中的稳定节点，发现了锚点机制</td><td>锚点机制的发现者，锚点觉醒纪元的开启者</td></tr></tbody></table><h3 id="_2-2-锚点觉醒纪元的奠基者" tabindex="-1">2.2 锚点觉醒纪元的奠基者 <a class="header-anchor" href="#_2-2-锚点觉醒纪元的奠基者" aria-label="Permalink to &quot;2.2 锚点觉醒纪元的奠基者&quot;">​</a></h3><table tabindex="0"><thead><tr><th>人物名称</th><th>所处时期</th><th>核心贡献</th><th>历史地位</th></tr></thead><tbody><tr><td>锚定公</td><td>-10000年至-9200年</td><td>锚觉者的弟子，系统研究锚点机制，建立第一个人工锚点，著有《锚点原理》</td><td>锚点技术的奠基人，人工锚点的发明者</td></tr><tr><td>共生子</td><td>-6000年至-5100年</td><td>将锚点技术与共生思想结合，创立&quot;锚点共生&quot;理论体系，著有《锚点共生论》</td><td>锚点共生理论的创立者，共生文明的思想导师</td></tr><tr><td>衡元公</td><td>-5000年至-4300年</td><td>建立第一个以锚点为基础的共生型城邦&quot;衡元城&quot;，并成功抵御掠夺式文明的攻击</td><td>第一个共生型城邦的建立者，共生制度的实践者</td></tr><tr><td>万族使</td><td>-2000年至-1200年</td><td>发起第一次&quot;万族共生大会&quot;，奔走于数十个种族之间倡导共生联合</td><td>万族联合的倡导者，跨种族共生的先驱</td></tr></tbody></table><h3 id="_2-3-共生体系建立期的建国者" tabindex="-1">2.3 共生体系建立期的建国者 <a class="header-anchor" href="#_2-3-共生体系建立期的建国者" aria-label="Permalink to &quot;2.3 共生体系建立期的建国者&quot;">​</a></h3><table tabindex="0"><thead><tr><th>人物名称</th><th>所处时期</th><th>核心贡献</th><th>历史地位</th></tr></thead><tbody><tr><td>立宪公</td><td>-1000年至-900年</td><td>共生宪法起草委员会主席，主持起草《共生宪法》，推动宪法全民公投通过</td><td>共生宪法的主要起草者，共生文明的立宪之父</td></tr><tr><td>执法公</td><td>-900年至-780年</td><td>第一任共生执行委员会主席，主持建立共生文明的行政体系与法律执行机制</td><td>共生行政体系的建立者，第一任行政首脑</td></tr><tr><td>司法母</td><td>-900年至-800年</td><td>第一任共生法院首席大法官，建立共生文明的司法体系与违宪审查制度</td><td>共生司法体系的建立者，第一任司法首脑</td></tr><tr><td>三百师</td><td>-500年至-300年</td><td>主持三百套本源修炼体系的发掘与整理工作，带领团队完成全部三百套体系的验证</td><td>三百套体系的总整理者，修炼开放的工程总指挥</td></tr><tr><td>倍增公</td><td>-300年至-220年</td><td>主持倍增果实的技术化应用研究，实现百倍推演增幅技术的工程化突破</td><td>倍增果实技术化的首席科学家，推演迭代体系的推动者</td></tr></tbody></table><h3 id="_2-4-开放与激活期的领导者" tabindex="-1">2.4 开放与激活期的领导者 <a class="header-anchor" href="#_2-4-开放与激活期的领导者" aria-label="Permalink to &quot;2.4 开放与激活期的领导者&quot;">​</a></h3><table tabindex="0"><thead><tr><th>人物名称</th><th>所处时期</th><th>核心贡献</th><th>历史地位</th></tr></thead><tbody><tr><td>开放公</td><td>-100年至-50年</td><td>主持三百套本源修炼体系的全面开放工作，建立修炼资源配给制度与导师网络</td><td>三百套体系开放的总指挥，&quot;人人有路&quot;的践行者</td></tr><tr><td>激活公</td><td>-50年至元年</td><td>主持20%激活战略的实施，带领团队在50年内完成20%众生的激活目标</td><td>20%激活战略的总指挥，共生文明新纪元的开启者</td></tr><tr><td>升维公</td><td>元年至80年</td><td>主持首次升维工程，推动四阶段升维路径的实施，实现首次阶段性升维</td><td>首次升维的总工程师，升维纪元的领导者</td></tr></tbody></table><h3 id="_2-5-万族共和与跨位面时代的探索者" tabindex="-1">2.5 万族共和与跨位面时代的探索者 <a class="header-anchor" href="#_2-5-万族共和与跨位面时代的探索者" aria-label="Permalink to &quot;2.5 万族共和与跨位面时代的探索者&quot;">​</a></h3><table tabindex="0"><thead><tr><th>人物名称</th><th>所处时期</th><th>核心贡献</th><th>历史地位</th></tr></thead><tbody><tr><td>万族共主</td><td>100年至200年</td><td>主持万族共和的成立工作，推动万族名录编纂与跨种族融合政策</td><td>万族共和的缔造者，第一任万族共主</td></tr><tr><td>位面母</td><td>500年至650年</td><td>第一任位面管理局局长，主持大规模跨位面探索计划，建立位面坐标总库</td><td>跨位面探索的开拓者，位面管理体系的建立者</td></tr><tr><td>考古公</td><td>800年至950年</td><td>主持复制镜异地考古方案的最终成熟，推动跨位面考古进入规模化时代</td><td>考古方案的集大成者，跨位面考古的奠基人</td></tr><tr><td>时律公</td><td>1000年至1150年</td><td>主持时间回溯技术的突破，推动先观测后有限干涉准则的确立</td><td>时间回溯技术的领导者，时间法则准则的制定者</td></tr></tbody></table><h2 id="三、重要组织" tabindex="-1">三、重要组织 <a class="header-anchor" href="#三、重要组织" aria-label="Permalink to &quot;三、重要组织&quot;">​</a></h2><h3 id="_3-1-最高权力机构" tabindex="-1">3.1 最高权力机构 <a class="header-anchor" href="#_3-1-最高权力机构" aria-label="Permalink to &quot;3.1 最高权力机构&quot;">​</a></h3><table tabindex="0"><thead><tr><th>组织名称</th><th>成立时间</th><th>核心职能</th><th>历史作用</th></tr></thead><tbody><tr><td>锚点议事会</td><td>-900年</td><td>共生文明最高权力机构，由万族代表按比例组成，行使立法权与重大事项决定权</td><td>共生文明的最高决策机构，所有重大法律与战略的制定者</td></tr><tr><td>共生执行委员会</td><td>-900年</td><td>共生文明最高行政机构，负责宪法与法律的执行、日常治理</td><td>共生文明的最高行政机关，法律与政策的执行者</td></tr><tr><td>共生法院</td><td>-900年</td><td>共生文明最高司法机构，独立行使审判权，负责违宪审查与重大案件审理</td><td>共生文明的最高司法机关，法治的守护者</td></tr><tr><td>锚点监督委员会</td><td>-900年</td><td>独立监督机构，负责对所有权力机构进行监督，防止权力滥用</td><td>共生文明的独立监督机关，权力制衡的关键一环</td></tr></tbody></table><h3 id="_3-2-专门管理机构" tabindex="-1">3.2 专门管理机构 <a class="header-anchor" href="#_3-2-专门管理机构" aria-label="Permalink to &quot;3.2 专门管理机构&quot;">​</a></h3><table tabindex="0"><thead><tr><th>组织名称</th><th>成立时间</th><th>核心职能</th><th>历史作用</th></tr></thead><tbody><tr><td>位面管理局</td><td>500年</td><td>负责位面坐标总库维护、穿梭许可审批、跨位面考古管理、跨位面外交协调</td><td>跨位面交互的主管机构，位面探索的管理者</td></tr><tr><td>时间法则委员会</td><td>1000年</td><td>负责时间回溯操作的审批、时间法则研究、时间悖论防控监督</td><td>时间回溯操作的审批与监督机构，时间法则安全的守护者</td></tr><tr><td>时间法则审计委员会</td><td>1050年</td><td>负责时间回溯操作的事后审计，确认未造成不可控的时间线扰动</td><td>时间操作的独立审计机构，时间回溯安全的最后防线</td></tr><tr><td>跨位面伦理委员会</td><td>600年</td><td>制定和解释跨位面伦理准则，审批高风险跨位面交互项目，受理伦理违规投诉</td><td>跨位面交互的伦理监督机构，文明主体性的守护者</td></tr><tr><td>知识回传审计处</td><td>850年</td><td>负责知识回传操作的审计，确保回传内容符合&quot;仅回传知识&quot;原则</td><td>知识回传的审计机构，跨位面污染防控的关键环节</td></tr></tbody></table><h3 id="_3-3-研究与教育机构" tabindex="-1">3.3 研究与教育机构 <a class="header-anchor" href="#_3-3-研究与教育机构" aria-label="Permalink to &quot;3.3 研究与教育机构&quot;">​</a></h3><table tabindex="0"><thead><tr><th>组织名称</th><th>成立时间</th><th>核心职能</th><th>历史作用</th></tr></thead><tbody><tr><td>锚点研究院</td><td>-8000年</td><td>锚点机制的基础研究与应用开发，人工锚点的建设与维护</td><td>锚点技术的核心研究机构，共生文明的技术源头之一</td></tr><tr><td>三百套体系整理委员会</td><td>-500年</td><td>三百套本源修炼体系的发掘、整理、验证与持续优化</td><td>三百套体系的整理与维护机构，修炼开放的技术支撑</td></tr><tr><td>共生大学联盟</td><td>-700年</td><td>高等教育与修炼教育的联合体，负责高级人才培养与学术研究</td><td>共生文明的最高学府联盟，人才培养与学术创新的核心</td></tr><tr><td>跨位面考古学院</td><td>550年</td><td>培养跨位面考古专业人才，开展考古技术研究与方法论创新</td><td>跨位面考古的人才培养与技术研发中心</td></tr><tr><td>时间法则研究所</td><td>950年</td><td>时间法则的基础理论研究与时间回溯技术的研发</td><td>时间法则研究的核心机构，时间回溯技术的发源地</td></tr></tbody></table><h3 id="_3-4-军事与安全组织" tabindex="-1">3.4 军事与安全组织 <a class="header-anchor" href="#_3-4-军事与安全组织" aria-label="Permalink to &quot;3.4 军事与安全组织&quot;">​</a></h3><table tabindex="0"><thead><tr><th>组织名称</th><th>成立时间</th><th>核心职能</th><th>历史作用</th></tr></thead><tbody><tr><td>共生防御军</td><td>-850年</td><td>共生文明的正规防御力量，负责位面防御与外部威胁应对</td><td>共生文明的主要军事力量，国家安全的捍卫者</td></tr><tr><td>位面巡逻队</td><td>520年</td><td>负责已探知位面的巡逻与安全监控，应对跨位面安全事件</td><td>跨位面安全的一线力量，位面秩序的维护者</td></tr><tr><td>法则污染应急队</td><td>600年</td><td>负责法则污染与能量污染事件的应急响应与污染清除</td><td>法则污染的应急处置力量，宇宙环境的守护者</td></tr><tr><td>时间悖论应急组</td><td>1020年</td><td>负责时间悖论事件的应急响应与因果修复操作</td><td>时间悖论的应急处置力量，时间线稳定的最后保障</td></tr></tbody></table><h3 id="_3-5-民间与社会组织" tabindex="-1">3.5 民间与社会组织 <a class="header-anchor" href="#_3-5-民间与社会组织" aria-label="Permalink to &quot;3.5 民间与社会组织&quot;">​</a></h3><table tabindex="0"><thead><tr><th>组织名称</th><th>成立时间</th><th>核心职能</th><th>历史作用</th></tr></thead><tbody><tr><td>万族共生大会</td><td>-2000年</td><td>万族代表的定期集会，讨论跨种族共生事务，促进文化交流</td><td>万族交流的重要平台，万族共和的前身组织</td></tr><tr><td>修炼者协会</td><td>-600年</td><td>修炼者的行业自治组织，负责修炼者权益维护、行业规范制定</td><td>修炼者的自治组织，修炼行业规范化的推动者</td></tr><tr><td>消费者协会</td><td>-650年</td><td>消费者权益保护组织，负责消费维权、消费教育、社会监督</td><td>消费者权益的代言人，市场秩序的社会监督者</td></tr><tr><td>环境保护联盟</td><td>-550年</td><td>环境保护的民间联合组织，负责环境监督、环保教育、生态修复志愿活动</td><td>环境保护的社会力量，宇宙生态文明的推动者</td></tr><tr><td>跨位面友好协会</td><td>580年</td><td>促进跨位面文明友好交流的民间组织，负责民间外交、文化交流</td><td>跨位面民间外交的核心力量，文明间理解的桥梁</td></tr></tbody></table><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>关键人物与组织是锚点共生文明历史的鲜活载体。从远古的思想先驱到当代的文明领导者，从最高权力机构到民间社会组织，每一个人物与组织都在共生文明的宏大叙事中扮演着不可替代的角色。他们的奋斗与贡献，共同编织了锚点共生文明从无到有、从小到大、从本位面到全宇宙的壮丽史诗。</p><h2 id="关联文档" tabindex="-1">关联文档 <a class="header-anchor" href="#关联文档" aria-label="Permalink to &quot;关联文档&quot;">​</a></h2><ul><li>70-纪元划分总表</li><li>49-治理框架与权力制衡</li><li>77-万族共和成立</li></ul>',30)])])}const c=d(e,[["render",o]]);export{_ as __pageData,c as default};
